// Inline the first two cards so the initial view and the first switch never wait on the network.
(function () {
  window.flashcardAssetsPartial = true;
  const assets = window.flashcardAssets = window.flashcardAssets || {};
  const morning = 'data:image/avif;base64,';
  assets['assets/scenes/textbook/morning.webp'] = morning;
  assets['assets/scenes-card/textbook/morning.webp'] = morning;
  assets['assets/scenes-card-webp/textbook/morning.webp'] = morning;
  assets['assets/scenes-card-lite/textbook/morning.avif'] = morning;
  const afternoon = 'data:image/avif;base64,';
  assets['assets/scenes/textbook/afternoon.webp'] = afternoon;
  assets['assets/scenes-card/textbook/afternoon.webp'] = afternoon;
  assets['assets/scenes-card-webp/textbook/afternoon.webp'] = afternoon;
  assets['assets/scenes-card-lite/textbook/afternoon.avif'] = afternoon;
})();
